with verdict as (
    select 'DEMO_TARGET1_INS' as target,
           (select count(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS) as baseline_count,
           (select count(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS) as migrated_count,
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS) as baseline_checksum,
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS) as migrated_checksum,
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS minus select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS)) as baseline_minus_count,
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS minus select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_INS)) as migrated_minus_count
    union all
    select 'DEMO_TARGET1_UPD',
           (select count(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD),
           (select count(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD minus select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD)),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD minus select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET1_UPD))
    union all
    select 'DEMO_TARGET2',
           (select count(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET2),
           (select count(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET2),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET2),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET2),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET2 minus select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET2)),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET2 minus select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET2))
    union all
    select 'DEMO_TARGET21',
           (select count(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET21),
           (select count(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET21),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET21),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET21),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET21 minus select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET21)),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET21 minus select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET21))
    union all
    select 'DEMO_TARGET3',
           (select count(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET3),
           (select count(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET3),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET3),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET3),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET3 minus select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET3)),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET3 minus select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET3))
    union all
    select 'DEMO_TARGET5',
           (select count(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET5),
           (select count(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET5),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET5),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET5),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET5 minus select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET5)),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET5 minus select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET5))
    union all
    select 'DEMO_TARGET6',
           (select count(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET6),
           (select count(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET6),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET6),
           (select hash_agg(*) from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET6),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET6 minus select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET6)),
           (select count(*) from (select * from DEVIN_MIGRATION_DEMO.PYSPARK_INFORMATICA_20260809T234500Z.DEMO_TARGET6 minus select * from DEVIN_MIGRATION_DEMO.BASELINE_INFORMATICA_20260809T234500Z.DEMO_TARGET6))
)
select target, baseline_count, migrated_count, baseline_checksum, migrated_checksum,
       baseline_minus_count, migrated_minus_count,
       case when baseline_count = migrated_count
                  and baseline_checksum = migrated_checksum
                  and baseline_minus_count = 0
                  and migrated_minus_count = 0
            then 'PASS' else 'FAIL' end as verdict
from verdict
order by target;
